from typing import List, Dict, Any

from app.ai.agents.base_agent import BaseAgent
from app.ai.orchestrator.state import LexIntelState
from app.ai.logging.logger import AILogger

logger = AILogger("agent.outcome_prediction")

_DISCLAIMER = (
    "⚠️ AI DISCLAIMER: This prediction is generated by an AI system and is NOT legal advice. "
    "Probabilities are estimates based on available information and similar cases. "
    "Actual outcomes depend on many factors including judicial discretion, new evidence, "
    "and legal arguments. Always consult a qualified lawyer before taking legal action."
)


class OutcomePredictionAgent(BaseAgent):
    """
    Phase 3B — Agent 1: Case Outcome Prediction

    Consumes completed Phase 3A state (document intelligence, legal research,
    similar cases, evidence analysis) and generates probabilistic outcome predictions
    with full reasoning chains and confidence scores.

    Never presents predictions as certainties. Always includes disclaimers.
    """

    agent_name = "outcome_prediction"
    prompt_name = "outcome_prediction"

    async def execute(self, state: LexIntelState) -> LexIntelState:
        doc_intel = state.get("document_intelligence") or {}
        legal_research = state.get("legal_research") or {}
        similar_cases = state.get("similar_cases") or []
        evidence_analysis = state.get("evidence_analysis") or {}
        evidence_items = state.get("evidence_items") or []
        missing_hints = state.get("missing_evidence_hints") or []
        evidence_timeline = state.get("evidence_timeline") or []

        # Build compact context — guard every value against None
        _sanitized = state.get("sanitized_input") or ""
        case_summary = doc_intel.get("summary") or _sanitized
        legal_summary = legal_research.get("research_summary") or ""
        applicable_acts = ", ".join(legal_research.get("applicable_acts") or [])
        remedies = "; ".join((legal_research.get("remedies") or [])[:5])

        similar_verdicts = "; ".join(
            f"{c.get('case_name','?')} → {c.get('verdict','?')} ({c.get('year','')})"
            for c in (similar_cases or [])[:5]
        )

        evidence_summary = evidence_analysis.get("analysis_summary") or ""
        evidence_count = len(evidence_items)
        missing_count = len(missing_hints)
        missing_list = "; ".join(missing_hints[:5])

        timeline_summary = "; ".join(
            (e.get("event_description") or "") for e in (evidence_timeline or [])[:5]
        )

        prompt = self.get_prompt()
        response = await self.invoke_llm(
            prompt.system,
            prompt.render_user(
                case_summary=case_summary[:1000],
                legal_summary=legal_summary[:800],
                applicable_acts=applicable_acts[:400],
                remedies=remedies[:400],
                similar_verdicts=similar_verdicts[:600],
                evidence_summary=evidence_summary[:600],
                evidence_count=str(evidence_count),
                missing_count=str(missing_count),
                missing_list=missing_list[:300],
                timeline_summary=timeline_summary[:400],
            ),
        )
        parsed = self.parse_json_response(response.content)

        # Always inject the disclaimer
        parsed["disclaimer"] = _DISCLAIMER
        parsed["ai_generated"] = True

        state["outcome_prediction"] = parsed

        logger.info(
            "Outcome prediction complete",
            strength=parsed.get("case_strength_score"),
            probability=parsed.get("probability_of_success"),
            confidence=parsed.get("confidence_level"),
        )
        return state
